// Strategy interface
interface DiscountStrategy {
    double applyDiscount(double cartTotal);
}

// Concrete strategies
class PremiumMemberDiscount implements DiscountStrategy {
    public double applyDiscount(double cartTotal) {
        return cartTotal * 0.85; // 15% off for premium
    }
}

class BulkOrderDiscount implements DiscountStrategy {
    public double applyDiscount(double cartTotal) {
        return cartTotal > 1000 ? cartTotal * 0.90 : cartTotal; // 10% off if over 1000
    }
}

class NoDiscount implements DiscountStrategy {
    public double applyDiscount(double cartTotal) {
        return cartTotal; // No discount applied
    }
}

// Context class
class CartService {
    private final DiscountStrategy discountStrategy;

    public CartService(DiscountStrategy discountStrategy) {
        this.discountStrategy = discountStrategy; // Strategy injected, not selected internally
    }

    public double calculateFinalPrice(double cartTotal) {
        return discountStrategy.applyDiscount(cartTotal); // Delegates to strategy
    }
}

// Strategy interface
interface PaymentStrategy {
    PaymentResult processPayment(Order order, double amount);
}

// Concrete strategies
@Component("creditCard")
class CreditCardPayment implements PaymentStrategy {
    public PaymentResult processPayment(Order order, double amount) {
        // Call payment gateway, validate card
        return new PaymentResult(true, "Card charged: " + amount);
    }
}

@Component("upi")
class UPIPayment implements PaymentStrategy {
    public PaymentResult processPayment(Order order, double amount) {
        // Generate UPI QR code, wait for callback
        return new PaymentResult(true, "UPI transaction ID: UPI" + order.id());
    }
}

@Component("cod")
class CODPayment implements PaymentStrategy {
    public PaymentResult processPayment(Order order, double amount) {
        // Mark order as pending payment on delivery
        return new PaymentResult(true, "COD order placed");
    }
}

// Context class
@Service
class PaymentService {
    private final PaymentStrategy paymentStrategy;

    public PaymentService(@Qualifier("creditCard") PaymentStrategy paymentStrategy) {
        this.paymentStrategy = paymentStrategy; // Strategy injected by Spring
    }

    public PaymentResult processOrderPayment(Order order, double amount) {
        return paymentStrategy.processPayment(order, amount); // Delegates without knowing type
    }
}

record Order(Long id, String item) {}
record PaymentResult(boolean success, String message) {}

record Employee(String name, int age, double salary) {}

class ComparatorDemo {
    public void demonstrateStrategies() {
        var employees = List.of(
            new Employee("Alice", 28, 75000),
            new Employee("Bob", 35, 90000),
            new Employee("Charlie", 28, 80000)
        );

        // Strategy 1: Sort by name using lambda (anonymous strategy)
        var byName = new ArrayList<>(employees);
        byName.sort((e1, e2) -> e1.name().compareTo(e2.name()));

        // Strategy 2: Sort by age then salary using Comparator.comparing
        var byAgeThenSalary = new ArrayList<>(employees);
        byAgeThenSalary.sort(
            Comparator.comparing(Employee::age)
                      .thenComparing(Employee::salary) // Chained strategies
        );

        // Strategy 3: Custom strategy class for salary descending
        var bySalaryDesc = new ArrayList<>(employees);
        bySalaryDesc.sort(new SalaryDescendingComparator());
    }
}

// Explicit strategy class
class SalaryDescendingComparator implements Comparator<Employee> {
    public int compare(Employee e1, Employee e2) {
        return Double.compare(e2.salary(), e1.salary()); // Reversed for descending
    }
}

// Strategy interface
interface NotificationStrategy {
    void sendNotification(String recipient, String message);
}

// Concrete strategies with qualifiers
@Component
@Qualifier("email")
class EmailNotification implements NotificationStrategy {
    public void sendNotification(String recipient, String message) {
        // Send via SMTP
        System.out.println("Email to " + recipient + ": " + message);
    }
}

@Component
@Qualifier("sms")
class SMSNotification implements NotificationStrategy {
    public void sendNotification(String recipient, String message) {
        // Send via SMS gateway
        System.out.println("SMS to " + recipient + ": " + message);
    }
}

@Component
@Qualifier("push")
class PushNotification implements NotificationStrategy {
    public void sendNotification(String recipient, String message) {
        // Send via Firebase
        System.out.println("Push to " + recipient + ": " + message);
    }
}

// Context with specific strategy injection
@Service
class OrderNotificationService {
    private final NotificationStrategy notificationStrategy;

    public OrderNotificationService(@Qualifier("email") NotificationStrategy notificationStrategy) {
        this.notificationStrategy = notificationStrategy; // Spring injects email strategy
    }

    public void notifyCustomer(String recipient, String orderDetails) {
        notificationStrategy.sendNotification(recipient, orderDetails);
    }
}

// Advanced: Map injection for runtime selection
@Service
class DynamicNotificationService {
    private final Map<String, NotificationStrategy> strategies;

    public DynamicNotificationService(Map<String, NotificationStrategy> strategies) {
        this.strategies = strategies; // Spring injects map: {"email":EmailNotification, "sms":SMSNotification, "push":PushNotification}
    }

    public void sendNotification(String type, String recipient, String message) {
        var strategy = strategies.get(type); // Runtime selection based on type parameter
        if (strategy != null) strategy.sendNotification(recipient, message);
    }
}
